import * as XLSX from "xlsx";
import {playerSameOrigin} from "../player_access";
import type {UiV2Context,UiV2Env} from "./context";
import {esc,renderUiV2Shell,uiV2Html} from "./shell";
import {handleUiV2ScreenshotImport} from "./screenshot_import";
import {handleUiV2HeroPowerScreenshot} from "./hero_power_screenshot";
import {handleUiV2DsSelectionScreenshot} from "./ds_selection_screenshot";
import {handleUiV2DsResultsScreenshot} from "./ds_results_screenshot";
import {playerPermitted} from "../player_access";
import {importTabs} from "./import_tabs";

type Player={id:number;display_name:string};
type VsRow={date:string;challenge:string;playerId:number|null;player:string;points:number|null;fingerprint:string;errors:string[];duplicate:boolean;noScore:boolean};
type VsPayload=Omit<VsRow,"errors"|"duplicate">;
type DsRow={date:string;team:"A"|"B"|"";playerId:number|null;player:string;selected:boolean;participated:boolean;opponent:string;ourScore:number|null;opponentScore:number|null;playerScore:number|null;fingerprint:string;errors:string[];duplicate:boolean};
type DsPayload=Omit<DsRow,"errors"|"duplicate">;
type Batch={id:number;public_id:string;dataset_type:string;file_name:string;status:string;row_count:number;imported_count:number;skipped_count:number;failed_count:number;created_at:string;rolled_back_at:string|null;created_by:string|null};
type Change={entity_key:string;before_json:string|null;after_json:string};
type StoredDay={challenge:string;target:number;scores:Array<{playerId:number;points:number}>};
type StoredDsEvent={battleTime:string|null;teamAOpponent:string;teamBOpponent:string;teamAScore:number|null;teamAEnemyScore:number|null;teamBScore:number|null;teamBEnemyScore:number|null;resultsFinalisedAt:string|null;players:Array<{playerId:number;team:string;selectionStatus:string;participated:number;playerScore:number|null}>};
type UnresolvedName={name:string;normalized:string;datasets:Set<string>;rows:number};
type MatchPlayer=Player&{is_active:number};
type MappingPreset={id:number;public_id:string;dataset_type:string;name:string;mapping_json:string};

const redirect=(r:Request,path:string)=>Response.redirect(new URL(path,r.url),303);
const normalHeader=(v:string)=>v.trim().toLowerCase().replace(/[_-]+/g," ").replace(/\s+/g," ");
const normalName=(v:string)=>v.trim().toLocaleLowerCase().replace(/\s+/g," ");
const cell=(row:Record<string,unknown>,aliases:string[])=>{const wanted=new Set(aliases.map(normalHeader));for(const [key,value] of Object.entries(row))if(wanted.has(normalHeader(key)))return value;return ""};
const validDate=(v:string)=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(`${v}T12:00:00Z`));
const excelDate=(value:unknown)=>{if(value instanceof Date)return value.toISOString().slice(0,10);if(typeof value==="number"){const parsed=XLSX.SSF.parse_date_code(value);return parsed?`${parsed.y}-${String(parsed.m).padStart(2,"0")}-${String(parsed.d).padStart(2,"0")}`:""}const text=String(value??"").trim();if(validDate(text))return text;const parts=text.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);return parts?`${parts[3]}-${parts[2].padStart(2,"0")}-${parts[1].padStart(2,"0")}`:""};
const points=(value:unknown)=>{const text=String(value??"").trim().replaceAll(",","").toUpperCase(),match=text.match(/^([0-9]+(?:\.[0-9]+)?)\s*([KMB])?$/);if(!match)return null;const factor=match[2]==="B"?1e9:match[2]==="M"?1e6:match[2]==="K"?1e3:1,result=Math.round(Number(match[1])*factor);return Number.isSafeInteger(result)&&result>=0?result:null};
const yes=(value:unknown)=>["yes","y","true","1"].includes(String(value??"").trim().toLowerCase());
const whole=(value:unknown)=>{const text=String(value??"").trim().replaceAll(",","");if(!text)return null;const n=Number(text);return Number.isSafeInteger(n)&&n>=0?n:null};
const weekday=(date:string)=>validDate(date)?new Intl.DateTimeFormat("en-GB",{weekday:"long",timeZone:"UTC"}).format(new Date(`${date}T12:00:00Z`)):"";
const displayDate=(date:string)=>validDate(date)?date.split("-").reverse().join("/"):date||"—";
const fmt=(n:number|null)=>n===null?"—":n>=1e9?`${Number((n/1e9).toFixed(2))}B`:n>=1e6?`${Number((n/1e6).toFixed(2))}M`:n.toLocaleString("en-GB");
const digest=async(value:string)=>Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value)))).map(x=>x.toString(16).padStart(2,"0")).join("");

const css=`<style>.ic-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.ic-card{padding:20px;border:1px solid var(--ui-line);border-radius:15px;background:var(--ui-surface-2)}.ic-card h2{margin:0 0 7px;font-size:1.03rem}.ic-card p{margin:0;color:var(--ui-muted);font-size:.76rem;line-height:1.55}.ic-tag{display:inline-block;margin-bottom:10px;padding:5px 8px;border-radius:999px;background:var(--ui-surface-3);color:var(--ui-accent);font-size:.61rem;font-weight:900;text-transform:uppercase}.ic-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.ic-button{display:inline-flex;align-items:center;justify-content:center;padding:10px 13px;border:0;border-radius:9px;background:var(--ui-button);color:var(--ui-button-text);font-size:.72rem;font-weight:900;text-decoration:none;cursor:pointer}.ic-button.secondary{border:1px solid var(--ui-line-strong);background:var(--ui-surface-3);color:var(--ui-navigation)}.ic-button.danger{border:1px solid color-mix(in srgb,var(--ui-danger) 45%,var(--ui-line));background:transparent;color:var(--ui-danger)}.ic-upload{display:grid;gap:12px}.ic-field span{display:block;margin-bottom:6px;color:var(--ui-secondary);font-size:.7rem;font-weight:850}.ic-field input,.ic-field select,.ic-table select{width:100%;padding:11px;border:1px solid var(--ui-line-strong);border-radius:9px;background:var(--ui-surface-3);color:var(--ui-text)}.ic-notice{margin-bottom:15px;padding:12px 14px;border:1px solid var(--ui-line);border-radius:11px;background:var(--ui-surface-2);color:var(--ui-muted);font-size:.76rem}.ic-notice.good{border-color:color-mix(in srgb,var(--ui-success) 42%,var(--ui-line));color:var(--ui-success)}.ic-notice.bad{border-color:color-mix(in srgb,var(--ui-danger) 42%,var(--ui-line));color:var(--ui-danger)}.ic-table-wrap{overflow:auto;border:1px solid var(--ui-line);border-radius:13px;background:var(--ui-surface-2)}.ic-table{width:100%;min-width:760px;border-collapse:collapse}.ic-table th,.ic-table td{padding:10px 11px;border-bottom:1px solid var(--ui-line);font-size:.71rem;text-align:left}.ic-table th{color:var(--ui-muted);font-size:.61rem;text-transform:uppercase}.ic-error{color:var(--ui-danger)}.ic-skip{color:var(--ui-warning)}.ic-history{display:grid;gap:9px;margin-top:17px}.ic-batch{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:13px;align-items:center;padding:14px;border:1px solid var(--ui-line);border-radius:12px;background:var(--ui-surface-2)}.ic-batch strong,.ic-batch span{display:block}.ic-batch span{margin-top:4px;color:var(--ui-muted);font-size:.67rem}.ic-empty{padding:22px;color:var(--ui-muted);text-align:center}@media(max-width:720px){.ic-grid{grid-template-columns:1fr}.ic-batch{grid-template-columns:1fr}.ic-actions{display:grid}.ic-button{width:100%}}</style>`;

const audit=(env:UiV2Env,context:UiV2Context,action:string,id:string,values:unknown)=>env.DB.prepare("INSERT INTO audit_log(public_id,actor_account_id,actor_display_name,action,entity_type,entity_id,source,new_values) VALUES(?,?,?,?,?,?,?,?)").bind(crypto.randomUUID(),context.user.accountId,context.user.displayName,action,"import_batch",id,"ui-v2-import-centre",JSON.stringify(values));
async function playerNames(env:UiV2Env){const [players,aliases]=await Promise.all([env.DB.prepare("SELECT id,display_name,is_active FROM players ORDER BY display_name COLLATE NOCASE").all<MatchPlayer>(),env.DB.prepare("SELECT a.alias_normalized,p.id,p.display_name FROM player_name_aliases a JOIN players p ON p.id=a.player_id").all<{alias_normalized:string;id:number;display_name:string}>()]),list=players.results??[],map=new Map<string,Player>(list.map(p=>[normalName(p.display_name),p]));for(const alias of aliases.results??[])map.set(alias.alias_normalized,{id:alias.id,display_name:alias.display_name});return{players:list,map}}

async function home(request:Request,env:UiV2Env,context:UiV2Context){
  const [batchRows,presetRows]=await Promise.all([env.DB.prepare("SELECT b.id,b.public_id,b.dataset_type,b.file_name,b.status,b.row_count,b.imported_count,b.skipped_count,b.failed_count,b.created_at,b.rolled_back_at,a.display_name created_by FROM import_batches b LEFT JOIN accounts a ON a.id=b.created_by_account_id ORDER BY b.created_at DESC,b.id DESC LIMIT 20").all<Batch>(),env.DB.prepare("SELECT id,public_id,dataset_type,name,mapping_json FROM import_mapping_presets ORDER BY dataset_type,name COLLATE NOCASE").all<MappingPreset>()]),batches=batchRows.results??[],presets=presetRows.results??[];
  const state=new URL(request.url).searchParams.get("state"),notice=state==="imported"?'<div class="ic-notice good">Import completed. The batch can be reviewed or rolled back below.</div>':state==="rolled-back"?'<div class="ic-notice good">The import batch was rolled back successfully.</div>':state==="changed"?'<div class="ic-notice bad">Rollback stopped because imported data has been edited since the import.</div>':state==="matched"?'<div class="ic-notice good">Player names saved. Re-run the review to confirm the workbook is fully matched.</div>':"";
  const history=batches.map(b=>`<article class="ic-batch"><div><strong>${esc(b.file_name)}</strong><span>${b.dataset_type==="vs_history"?"VS history":b.dataset_type==="desert_storm_history"?"Desert Storm history":esc(b.dataset_type)} · ${b.imported_count} imported · ${b.skipped_count} skipped · ${esc(b.created_at)} · ${esc(b.created_by||"System")}${b.status==="rolled_back"?` · Rolled back ${esc(b.rolled_back_at||"")}`:""}</span></div>${b.status==="completed"?`<form method="post" action="/ui-v2/import-centre/${b.id}/rollback" data-confirm="Roll back this entire import batch? Later edits to imported data will prevent rollback." data-confirm-title="Roll back import" data-confirm-button="Roll back"><button class="ic-button danger" type="submit">Roll back batch</button></form>`:'<span class="ic-tag">Rolled back</span>'}</article>`).join("");
  const presetList=presets.map(p=>`<article class="ic-batch"><div><strong>${esc(p.name)}</strong><span>${p.dataset_type==="vs_history"?"VS history":"Desert Storm history"}</span></div><form method="post" action="/ui-v2/import-centre/mapper/presets/${p.id}/delete" data-confirm="Delete this saved mapping preset?" data-confirm-title="Delete preset" data-confirm-button="Delete"><button class="ic-button danger" type="submit">Delete</button></form></article>`).join("");
  const body=`${css}${notice}<div class="ic-grid"><article class="ic-card"><span class="ic-tag">Screenshots</span><h2>Screenshot imports</h2><p>Use OpenAI-assisted review for roster and Hero Power, daily VS scores, or Desert Storm selection and results.</p><div class="ic-actions"><a class="ic-button" href="/ui-v2/import-centre/screenshots">Open screenshot imports</a></div></article><article class="ic-card"><span class="ic-tag">Current data</span><h2>Player roster</h2><p>Use the existing roster preview to add, update or reactivate players before importing historical sheets.</p><div class="ic-actions"><a class="ic-button" href="/ui-v2/players/import">Open roster importer</a></div></article><article class="ic-card"><span class="ic-tag">Prepare migration</span><h2>Player Matching Review</h2><p>Scan the complete workbook for former players and historic spellings, then link each name before importing history.</p><form class="ic-upload" method="post" action="/ui-v2/import-centre/player-matching/preview" enctype="multipart/form-data"><label class="ic-field"><span>Complete Excel workbook</span><input type="file" name="file" accept=".xlsx" required></label><div class="ic-actions"><button class="ic-button" type="submit">Review player names</button></div></form></article><article class="ic-card"><span class="ic-tag">Flexible import</span><h2>Worksheet and column mapper</h2><p>Choose any worksheet and map its headings to VS or Desert Storm fields. Saved mappings can be reused on later exports.</p><form class="ic-upload" method="post" action="/ui-v2/import-centre/mapper/upload" enctype="multipart/form-data"><label class="ic-field"><span>Dataset</span><select name="dataset_type" required><option value="vs_history">VS history</option><option value="desert_storm_history">Desert Storm history</option></select></label><label class="ic-field"><span>Excel or CSV file</span><input type="file" name="file" accept=".xlsx,.csv" required></label><div class="ic-actions"><button class="ic-button" type="submit">Choose worksheet</button></div></form></article><article class="ic-card"><span class="ic-tag">House of Quack preset</span><h2>Direct historical import</h2><p>Your existing workbook headings are recognised automatically. Use the mapper above for another layout.</p><div class="ic-actions"><a class="ic-button secondary" href="/ui-v2/import-centre/vs/template.csv">VS template</a><a class="ic-button secondary" href="/ui-v2/import-centre/desert-storm/template.csv">Desert Storm template</a></div></article></div>${presets.length?`<section class="ic-history"><h2>Saved mapping presets</h2>${presetList}</section>`:""}<section class="ic-history"><h2>Import history</h2>${history||'<div class="ic-empty">No migration batches have been imported yet.</div>'}</section>`;
  return uiV2Html(renderUiV2Shell(context,{eyebrow:"Data Migration",title:"Import Centre",description:"Move existing alliance information into the platform safely, one dataset at a time.",body:importTabs("files")+body,activePath:"/ui-v2/import-centre",back:{href:"/ui-v2/leadership",label:"Leadership Console"}}));
}

async function scanPlayerNames(env:UiV2Env,file:File){if(file.size>8*1024*1024)throw new Error("The spreadsheet is larger than 8 MB.");if(!/\.xlsx$/i.test(file.name))throw new Error("Use an .xlsx workbook.");const book=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true}),{players,map}=await playerNames(env),unresolved=new Map<string,UnresolvedName>(),playerHeaders=new Set(["player","player name","member","member name","driver","vip"]),pointHeaders=new Set(["points","score","vs points","player score"]);const add=(nameValue:unknown,dataset:string)=>{const name=String(nameValue??"").trim();if(!name)return;const normalized=normalName(name);if(map.has(normalized))return;const item=unresolved.get(normalized)||{name,normalized,datasets:new Set<string>(),rows:0};item.datasets.add(dataset);item.rows++;unresolved.set(normalized,item)};for(const sheetName of book.SheetNames){const sheet=book.Sheets[sheetName],rows=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:"",raw:true});if(!rows.length)continue;const headers=Object.keys(rows[0]),nameColumns=headers.filter(header=>playerHeaders.has(normalHeader(header))),pointsColumn=headers.find(header=>pointHeaders.has(normalHeader(header)));for(const row of rows){const score=pointsColumn?points(row[pointsColumn]):undefined;if(pointsColumn&&(score===null||score===0))continue;for(const column of nameColumns)add(row[column],`${sheetName} · ${column}`)}}return{unresolved:[...unresolved.values()].sort((a,b)=>a.name.localeCompare(b.name)),players}}

function matchingPreview(context:UiV2Context,fileName:string,unresolved:UnresolvedName[],players:MatchPlayer[]){if(!unresolved.length)return uiV2Html(renderUiV2Shell(context,{eyebrow:"Data Migration",title:"Player Matching Review",description:"Every historic player name in this workbook is already matched.",body:`${css}<div class="ic-notice good">No unresolved player names were found. VS and Desert Storm history are ready for preview.</div><div class="ic-actions"><a class="ic-button" href="/ui-v2/import-centre">Return to Import Centre</a></div>`,activePath:"/ui-v2/import-centre",back:{href:"/ui-v2/import-centre",label:"Import Centre"}}));const options=players.map(p=>`<option value="${p.id}">${esc(p.display_name)}${p.is_active?"":" · Former"}</option>`).join(""),payload=esc(JSON.stringify(unresolved.map(x=>({name:x.name,normalized:x.normalized}))));const rows=unresolved.map((x,index)=>`<tr><td>${esc(x.name)}</td><td>${esc([...x.datasets].join(", "))}</td><td>${x.rows}</td><td><select name="choice_${index}" required><option value="">Choose…</option><option value="new">Create as former player</option>${options}</select></td></tr>`).join("");const body=`${css}<div class="ic-notice">${unresolved.length} historic ${unresolved.length===1?"name needs":"names need"} a decision. Link spelling variations to one permanent player; create a former player only when it represents a different person.</div><form method="post" action="/ui-v2/import-centre/player-matching/commit"><input type="hidden" name="file_name" value="${esc(fileName)}"><textarea name="payload" hidden>${payload}</textarea><div class="ic-table-wrap"><table class="ic-table"><thead><tr><th>Historic name</th><th>Found in</th><th>Rows</th><th>Match</th></tr></thead><tbody>${rows}</tbody></table></div><div class="ic-actions"><a class="ic-button secondary" href="/ui-v2/import-centre">Cancel</a><button class="ic-button" type="submit">Save player matches</button></div></form>`;return uiV2Html(renderUiV2Shell(context,{eyebrow:"Data Migration",title:"Player Matching Review",description:"Resolve historic names before importing performance records.",body,activePath:"/ui-v2/import-centre",back:{href:"/ui-v2/import-centre",label:"Import Centre"}}))}

async function commitPlayerMatches(request:Request,env:UiV2Env,context:UiV2Context){if(!playerSameOrigin(request,env))return new Response("Forbidden",{status:403});const form=await request.formData();let aliases:Array<{name:string;normalized:string}>;try{aliases=JSON.parse(String(form.get("payload")||"[]"))}catch{return new Response("Invalid matching preview",{status:400})}if(!Array.isArray(aliases)||!aliases.length||aliases.length>300)return new Response("Invalid matching preview",{status:400});const existing=await playerNames(env),validIds=new Set(existing.players.map(p=>p.id)),seen=new Set<string>();for(let index=0;index<aliases.length;index++){const name=String(aliases[index].name||"").trim(),normalized=normalName(name),choice=String(form.get(`choice_${index}`)||"");if(!name||name.length>80||aliases[index].normalized!==normalized||seen.has(normalized)||(!validIds.has(Number(choice))&&choice!=="new"))return new Response("The matching preview is no longer valid.",{status:400});seen.add(normalized)}let linked=0,created=0;for(let index=0;index<aliases.length;index++){const alias=aliases[index],choice=String(form.get(`choice_${index}`));if(choice==="new"){const player=await env.DB.prepare("INSERT INTO players(display_name,rank,is_active) VALUES(?,1,0) RETURNING id").bind(alias.name).first<{id:number}>();if(!player?.id)throw new Error("Former player could not be created");await env.DB.batch([env.DB.prepare("INSERT INTO player_rank_history(player_id,old_rank,new_rank,changed_by_account_id,note) VALUES (?,NULL,1,?,?)").bind(player.id,context.user.accountId,"Created for historic data import"),audit(env,context,"import.player.created",String(player.id),{displayName:alias.name,isActive:false})]);created++;continue}const playerId=Number(choice);await env.DB.batch([env.DB.prepare("INSERT INTO player_name_aliases(alias_name,alias_normalized,player_id,created_by_account_id) VALUES(?,?,?,?) ON CONFLICT(alias_normalized) DO UPDATE SET alias_name=excluded.alias_name,player_id=excluded.player_id,created_by_account_id=excluded.created_by_account_id").bind(alias.name,alias.normalized,playerId,context.user.accountId),audit(env,context,"import.player_alias.saved",alias.normalized,{alias:alias.name,playerId})]);linked++}await audit(env,context,"import.player_matching.completed",String(form.get("file_name")||"workbook"),{linked,created,total:aliases.length}).run();return redirect(request,"/ui-v2/import-centre?state=matched")}

const mappingFields={vs_history:[{key:"date",label:"Competition date",required:true,aliases:["date","competition date","vs date"]},{key:"player",label:"Player",required:true,aliases:["player","player name","member","member name","name"]},{key:"points",label:"Points",required:true,aliases:["points","score","vs points","contribution"]},{key:"challenge",label:"Challenge",required:false,aliases:["challenge","challenge name","day","vs day"]}],desert_storm_history:[{key:"date",label:"Event date",required:true,aliases:["event date","date","battle date"]},{key:"team",label:"Team",required:true,aliases:["team","squad"]},{key:"player",label:"Player",required:true,aliases:["player","player name","member","member name","name"]},{key:"selected",label:"Selected",required:true,aliases:["selected","selection"]},{key:"participated",label:"Took part",required:true,aliases:["took part","participated","played"]},{key:"opponent",label:"Opponent",required:true,aliases:["opponent","enemy"]},{key:"ourScore",label:"Our score",required:false,aliases:["our score","alliance score"]},{key:"opponentScore",label:"Opponent score",required:false,aliases:["opponent score","enemy score"]},{key:"playerScore",label:"Individual points",required:false,aliases:["individual points","player score","points"]}]} as const;
type MappedDataset=keyof typeof mappingFields;
const isMappedDataset=(v:string):v is MappedDataset=>v==="vs_history"||v==="desert_storm_history";
const draftPrefix=(context:UiV2Context)=>`import-drafts/${context.user.accountId}/`;
async function loadDraft(env:UiV2Env,context:UiV2Context,key:string){if(!key.startsWith(draftPrefix(context)))return null;const object=await env.ASSETS.get(key);if(!object)return null;if(Date.now()-object.uploaded.getTime()>2*60*60*1000){await env.ASSETS.delete(key);return null}return object}

async function uploadMappingDraft(request:Request,env:UiV2Env,context:UiV2Context){if(!playerSameOrigin(request,env))return new Response("Forbidden",{status:403});const form=await request.formData(),dataset=String(form.get("dataset_type")||""),file=form.get("file");if(!isMappedDataset(dataset)||!(file instanceof File)||!file.size||file.size>8*1024*1024||!/\.(xlsx|csv)$/i.test(file.name))return new Response("Choose a valid dataset and an Excel or CSV file up to 8 MB.",{status:400});const bytes=await file.arrayBuffer(),book=XLSX.read(bytes,{type:"array",cellDates:true});if(!book.SheetNames.length)return new Response("The file has no readable worksheets.",{status:400});const key=`${draftPrefix(context)}${crypto.randomUUID()}`;await env.ASSETS.put(key,bytes,{customMetadata:{fileName:file.name,dataset}});const cards=book.SheetNames.map(name=>{const sheet=book.Sheets[name],range=XLSX.utils.decode_range(sheet["!ref"]||"A1:A1"),rows=Math.max(0,range.e.r-range.s.r);return `<form class="ic-card" method="post" action="/ui-v2/import-centre/mapper/map"><input type="hidden" name="draft_key" value="${esc(key)}"><input type="hidden" name="dataset_type" value="${dataset}"><input type="hidden" name="sheet_name" value="${esc(name)}"><span class="ic-tag">${rows} data rows</span><h2>${esc(name)}</h2><p>Choose this worksheet and map its column headings.</p><div class="ic-actions"><button class="ic-button" type="submit">Map this worksheet</button></div></form>`}).join("");return uiV2Html(renderUiV2Shell(context,{eyebrow:"Data Migration",title:"Choose Worksheet",description:`${file.name} · ${dataset==="vs_history"?"VS history":"Desert Storm history"}`,body:`${css}<div class="ic-grid">${cards}</div>`,activePath:"/ui-v2/import-centre",back:{href:"/ui-v2/import-centre",label:"Import Centre"}}))}

