async function deleteMappingPreset(request:Request,env:UiV2Env,context:UiV2Context,id:number){if(!playerSameOrigin(request,env))return new Response("Forbidden",{status:403});const preset=await env.DB.prepare("SELECT public_id,name,dataset_type FROM import_mapping_presets WHERE id=?").bind(id).first<{public_id:string;name:string;dataset_type:string}>();if(!preset)return new Response("Preset not found",{status:404});await env.DB.batch([env.DB.prepare("DELETE FROM import_mapping_presets WHERE id=?").bind(id),audit(env,context,"import.mapping_preset.deleted",preset.public_id,{name:preset.name,dataset:preset.dataset_type})]);return redirect(request,"/ui-v2/import-centre")}

async function parseVs(env:UiV2Env,file:File):Promise<VsRow[]>{
  if(file.size>8*1024*1024)throw new Error("The spreadsheet is larger than 8 MB.");
  if(!/\.(xlsx|csv)$/i.test(file.name))throw new Error("Use an .xlsx or .csv file.");
  const book=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true}),sheet=book.Sheets[book.SheetNames.find(name=>normalHeader(name)==="vs points")||book.SheetNames[0]];if(!sheet)throw new Error("The spreadsheet has no readable worksheet.");
  const raw=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:"",raw:true});if(!raw.length)throw new Error("The spreadsheet contains no VS rows.");if(raw.length>5000)throw new Error("Import a maximum of 5,000 VS rows at a time.");
  const [{map:byName},fingerprints]=await Promise.all([playerNames(env),env.DB.prepare("SELECT fingerprint FROM import_row_fingerprints WHERE dataset_type='vs_history'").all<{fingerprint:string}>()]),known=new Set((fingerprints.results??[]).map(x=>x.fingerprint)),seen=new Set<string>();
  return Promise.all(raw.map(async source=>{const date=excelDate(cell(source,["date","competition date","vs date"])),supplied=String(cell(source,["challenge","challenge name","day","vs day"])).trim().replace(/\s+/g," ").slice(0,80),challenge=supplied||weekday(date),player=String(cell(source,["player","player name","name"])).trim(),matched=byName.get(normalName(player))||null,score=points(cell(source,["points","score","vs points","player score"])),noScore=score===null||score===0,fingerprint=await digest(JSON.stringify([date,challenge.toLowerCase(),matched?.id??normalName(player),score])),errors:string[]=[];if(!noScore){if(!validDate(date))errors.push("Invalid or missing date");if(!challenge)errors.push("Challenge is required");if(!player)errors.push("Player is required")}const duplicate=!noScore&&(known.has(fingerprint)||seen.has(fingerprint));if(!noScore)seen.add(fingerprint);return{date,challenge,playerId:matched?.id??null,player,points:score,fingerprint,errors,duplicate,noScore}}));
}

function vsPreview(context:UiV2Context,fileName:string,rows:VsRow[]){
  const bad=rows.some(x=>x.errors.length),ready=rows.filter(x=>!x.errors.length&&!x.duplicate&&!x.noScore).length,skipped=rows.length-ready,payload=esc(JSON.stringify({fileName,rows:rows.filter(x=>!x.noScore).map(({errors,duplicate,...row})=>row)}));
  const table=rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(displayDate(r.date))}</td><td>${esc(r.challenge||"—")}</td><td>${esc(r.player||"—")}</td><td>${fmt(r.points)}</td><td class="${r.errors.length?"ic-error":r.duplicate||r.noScore?"ic-skip":""}">${r.errors.length?esc(r.errors.join("; ")):r.noScore?"No score — skip":r.duplicate?"Already imported — skip":r.playerId===null?"New former player":"Ready"}</td></tr>`).join("");
  const body=`${css}<div class="ic-notice ${bad?"bad":"good"}">${bad?"Nothing has been saved. Correct the invalid rows and upload the file again.":`${ready} rows are ready and ${skipped} no-score or duplicate rows will be skipped.`}</div><div class="ic-table-wrap"><table class="ic-table"><thead><tr><th>#</th><th>Date</th><th>Challenge</th><th>Player</th><th>Points</th><th>Validation</th></tr></thead><tbody>${table}</tbody></table></div><div class="ic-actions"><a class="ic-button secondary" href="/ui-v2/import-centre">Cancel</a>${bad||!ready?"":`<form method="post" action="/ui-v2/import-centre/vs/commit"><textarea name="payload" hidden>${payload}</textarea><button class="ic-button" type="submit">Import ${ready} VS rows</button></form>`}</div>`;
  return uiV2Html(renderUiV2Shell(context,{eyebrow:"Data Migration",title:"VS Import Preview",description:"Review the historic scores before changing platform data.",body,activePath:"/ui-v2/import-centre",back:{href:"/ui-v2/import-centre",label:"Import Centre"}}));
}

async function parseDs(env:UiV2Env,file:File):Promise<DsRow[]>{
  if(file.size>8*1024*1024)throw new Error("The spreadsheet is larger than 8 MB.");if(!/\.(xlsx|csv)$/i.test(file.name))throw new Error("Use an .xlsx or .csv file.");
  const book=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true}),sheet=book.Sheets[book.SheetNames.find(name=>normalHeader(name)==="ds history")||book.SheetNames[0]];if(!sheet)throw new Error("The spreadsheet has no readable worksheet.");const raw=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:"",raw:true});if(!raw.length)throw new Error("The spreadsheet contains no Desert Storm rows.");if(raw.length>5000)throw new Error("Import a maximum of 5,000 Desert Storm rows at a time.");
  const [{map:byName},fingerprints]=await Promise.all([playerNames(env),env.DB.prepare("SELECT fingerprint FROM import_row_fingerprints WHERE dataset_type='desert_storm_history'").all<{fingerprint:string}>()]),known=new Set((fingerprints.results??[]).map(x=>x.fingerprint)),seen=new Set<string>();
  return Promise.all(raw.map(async source=>{const date=excelDate(cell(source,["event date","date","battle date"])),teamText=String(cell(source,["team"])).trim().toUpperCase(),team=teamText==="A"||teamText==="B"?teamText as "A"|"B":"",player=String(cell(source,["player","player name","name"])).trim(),matched=byName.get(normalName(player))||null,selected=yes(cell(source,["selected"])),participated=yes(cell(source,["took part","participated","played"])),opponent=String(cell(source,["opponent","enemy"])).trim().replace(/\s+/g," ").slice(0,80),ourScore=whole(cell(source,["our score","alliance score","ourscore"])),opponentScore=whole(cell(source,["opponent score","enemy score","opponentscore"])),playerScore=whole(cell(source,["individual points","player score","points","playerscore"])),fingerprint=await digest(JSON.stringify([date,team,matched?.id??normalName(player),selected,participated,opponent.toLowerCase(),ourScore,opponentScore,playerScore])),errors:string[]=[];if(!validDate(date))errors.push("Invalid or missing date");if(!team)errors.push("Team must be A or B");if(!player)errors.push("Player is required");if(!opponent)errors.push("Opponent is required");if(participated&&playerScore===null)errors.push("Participant points are required");const duplicate=known.has(fingerprint)||seen.has(fingerprint);seen.add(fingerprint);return{date,team,playerId:matched?.id??null,player,selected,participated,opponent,ourScore,opponentScore,playerScore,fingerprint,errors,duplicate}}));
}

function dsPreview(context:UiV2Context,fileName:string,rows:DsRow[]){const bad=rows.some(x=>x.errors.length),ready=rows.filter(x=>!x.errors.length&&!x.duplicate).length,skipped=rows.filter(x=>x.duplicate).length,payload=esc(JSON.stringify({fileName,rows:rows.map(({errors,duplicate,...row})=>row)})),table=rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(displayDate(r.date))}</td><td>${esc(r.team||"—")}</td><td>${esc(r.player||"—")}</td><td>${r.selected?"Selected":"Substitute"}</td><td>${r.participated?fmt(r.playerScore):"Did not play"}</td><td>${esc(r.opponent||"—")}</td><td class="${r.errors.length?"ic-error":r.duplicate?"ic-skip":""}">${r.errors.length?esc(r.errors.join("; ")):r.duplicate?"Already imported — skip":r.playerId===null?"New former player":"Ready"}</td></tr>`).join("");const body=`${css}<div class="ic-notice ${bad?"bad":"good"}">${bad?"Nothing has been saved. Correct the invalid rows and upload again.":`${ready} rows are ready and ${skipped} exact duplicates will be skipped. Unmatched names will be created as former players.`}</div><div class="ic-table-wrap"><table class="ic-table"><thead><tr><th>#</th><th>Date</th><th>Team</th><th>Player</th><th>Selection</th><th>Participation</th><th>Opponent</th><th>Validation</th></tr></thead><tbody>${table}</tbody></table></div><div class="ic-actions"><a class="ic-button secondary" href="/ui-v2/import-centre">Cancel</a>${bad||!ready?"":`<form method="post" action="/ui-v2/import-centre/desert-storm/commit"><textarea name="payload" hidden>${payload}</textarea><button class="ic-button" type="submit">Import ${ready} Desert Storm rows</button></form>`}</div>`;return uiV2Html(renderUiV2Shell(context,{eyebrow:"Data Migration",title:"Desert Storm Import Preview",description:"Review both teams and their historic participation before saving.",body,activePath:"/ui-v2/import-centre",back:{href:"/ui-v2/import-centre",label:"Import Centre"}}))}

async function currentDay(env:UiV2Env,date:string):Promise<StoredDay|null>{const day=await env.DB.prepare("SELECT challenge_name,daily_target FROM vs_days WHERE competition_date=?").bind(date).first<{challenge_name:string;daily_target:number}>();if(!day)return null;const scores=(await env.DB.prepare("SELECT player_id,points FROM vs_scores WHERE competition_date=? ORDER BY player_id").bind(date).all<{player_id:number;points:number}>()).results??[];return{challenge:day.challenge_name,target:day.daily_target,scores:scores.map(x=>({playerId:x.player_id,points:x.points}))}};
