  for(const row of rows){const playerKey=row.playerId===null?normalName(row.player):row.playerId,expected=await digest(JSON.stringify([row.date,row.challenge.toLowerCase(),playerKey,row.points]));if(!validDate(row.date)||!row.challenge||!row.player||row.player.length>80||(row.playerId!==null&&!ids.has(row.playerId))||!Number.isSafeInteger(row.points)||row.points<=0||row.fingerprint!==expected)return new Response("The preview no longer validates. Upload the file again.",{status:400})}
  const ready=rows.filter(r=>!existingFp.has(r.fingerprint)&&!seen.has(r.fingerprint)&&(seen.add(r.fingerprint),true));if(!ready.length)return redirect(request,"/ui-v2/import-centre");
  const newFormer=new Map<string,{id:number;name:string}>();for(const row of ready){if(row.playerId!==null)continue;const normalized=normalName(row.player),known=byName.get(normalized);if(known){row.playerId=known;continue}let created=newFormer.get(normalized);if(!created){const player=await env.DB.prepare("INSERT INTO players(display_name,rank,is_active,left_at) VALUES(?,1,0,CURRENT_TIMESTAMP) RETURNING id").bind(row.player).first<{id:number}>();if(!player?.id)throw new Error("Former player could not be created");created={id:player.id,name:row.player};newFormer.set(normalized,created);byName.set(normalized,player.id);ids.add(player.id);await env.DB.batch([env.DB.prepare("INSERT INTO player_rank_history(player_id,old_rank,new_rank,changed_by_account_id,note) VALUES (?,NULL,1,?,?)").bind(player.id,context.user.accountId,"Created automatically from historical VS import"),audit(env,context,"import.player.created",String(player.id),{displayName:row.player,isActive:false,source:"vs_history"})])}row.playerId=created.id}
  for(const row of ready)row.fingerprint=await digest(JSON.stringify([row.date,row.challenge.toLowerCase(),Number(row.playerId),row.points]));
  const dates=[...new Set(ready.map(r=>r.date))],targetRow=await env.DB.prepare("SELECT value FROM settings WHERE key='player_vs_daily_target'").first<{value:string}>(),target=Number(targetRow?.value||7200000),before=new Map<string,StoredDay|null>();for(const date of dates)before.set(date,await currentDay(env,date));
  const batch=await env.DB.prepare("INSERT INTO import_batches(public_id,dataset_type,file_name,row_count,imported_count,skipped_count,created_by_account_id) VALUES(?,?,?,?,?,?,?) RETURNING id,public_id").bind(crypto.randomUUID(),"vs_history",parsed.fileName.slice(0,255),rows.length,ready.length,rows.length-ready.length,context.user.accountId).first<{id:number;public_id:string}>();if(!batch)throw new Error("Import batch could not be created");
  for(const date of dates){const dateRows=ready.filter(r=>r.date===date),prior=before.get(date),merged=new Map((prior?.scores??[]).map(x=>[x.playerId,x.points]));dateRows.forEach(r=>merged.set(Number(r.playerId),r.points));const challenge=dateRows[dateRows.length-1].challenge,after:StoredDay={challenge,target:prior?.target??target,scores:[...merged].map(([playerId,score])=>({playerId,points:score})).sort((a,b)=>a.playerId-b.playerId)},statements:D1PreparedStatement[]=[env.DB.prepare("INSERT INTO vs_days(competition_date,challenge_name,daily_target,updated_by_account_id,updated_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(competition_date) DO UPDATE SET challenge_name=excluded.challenge_name,daily_target=excluded.daily_target,updated_by_account_id=excluded.updated_by_account_id,updated_at=CURRENT_TIMESTAMP").bind(date,after.challenge,after.target,context.user.accountId),env.DB.prepare("DELETE FROM vs_scores WHERE competition_date=?").bind(date)];after.scores.forEach(x=>statements.push(env.DB.prepare("INSERT INTO vs_scores(competition_date,player_id,points) VALUES(?,?,?)").bind(date,x.playerId,x.points)));statements.push(env.DB.prepare("INSERT INTO import_batch_changes(batch_id,entity_type,entity_key,operation,before_json,after_json) VALUES(?,?,?,?,?,?)").bind(batch.id,"vs_day",date,prior?"update":"insert",prior?JSON.stringify(prior):null,JSON.stringify(after)));await env.DB.batch(statements)}
